// Regression tests for two text-edit defects reproduced by a page that draws
// text under an ambient "-100 Tz" (negative horizontal text scaling) with a
// non-black fill -- the trait of a real Examplecorp RTV invoice (not committed;
// customer data). Fixture: tests/fixtures/neg_tz_grey_text.pdf (synthetic,
// generated by tests/fixtures/gen_neg_tz_grey_text.py).
//
//   Bug 1 (color): editing a grey (#dbd0d0) span turned the text black, because
//                  the original fill color is never captured/re-emitted.
//   Bug 2 (mirror): edited text rendered horizontally mirrored ("RTAV"->"VATR"),
//                   because the replacement inherits the ambient -100 Tz.
//
// Both assertions read the RESULT back via fitz stext (glyph argb + quad) after
// a save/reopen round-trip -- exactly what a viewer would render.
#include <gtest/gtest.h>
#include "textedit/ContentStreamEditor.h"
#include "textedit/TextEditModel.h"
#include "core/Document.h"
#include "core/Page.h"
#include "core/MuPdfContext.h"
#include <filesystem>
#include <memory>
#include <string>
#include <vector>

extern "C" {
#include <mupdf/fitz.h>
}

using namespace pdfe::textedit;
using namespace pdfe::core;

namespace {

struct EditedGlyph {
    char32_t c;
    uint32_t argb;   // sRGB, alpha in top 8 bits
    fz_quad quad;
};

// Apply "SHIP TO" -> "SHOP TO" on the fixture, save, reopen, and return the
// glyphs of the edited line (the one containing 'O','P') as rendered by stext.
std::vector<EditedGlyph> editAndReadBack() {
    auto context = std::make_shared<MuPdfContext>();
    // Fixture is the committed synthetic PDF; PDFE_NEG_TZ_FIXTURE can override it
    // (used to investigate the real, non-committable customer PDF locally).
    std::filesystem::path fixture =
        std::filesystem::path(TEST_FIXTURES_DIR) / "neg_tz_grey_text.pdf";
    if (const char* env = std::getenv("PDFE_NEG_TZ_FIXTURE"))
        fixture = env;
    EXPECT_TRUE(std::filesystem::exists(fixture)) << fixture.string();

    auto document = Document::open(context, fixture);
    EXPECT_NE(document, nullptr);
    auto page = document->page(0);
    EXPECT_NE(page, nullptr);

    auto blocks = page->extractText();
    TextEditModel model(blocks);
    std::vector<TextSpan> spans;
    for (int i = 0; i < model.spanCount(); ++i) spans.push_back(model.span(i));

    int target = -1;
    for (int i = 0; i < static_cast<int>(spans.size()); ++i) {
        if (spans[i].text.find(U"SHIP TO") != std::u32string::npos) { target = i; break; }
    }
    EXPECT_GE(target, 0) << "fixture must contain a 'SHIP TO' span";

    ContentStreamEditor editor(context.get());
    std::vector<std::pair<int, std::u32string>> mods;
    mods.push_back({target, U"SHOP TO"});
    editor.applyEdits(page.get(), document.get(), spans, mods);

    std::filesystem::path out =
        std::filesystem::temp_directory_path() / "pdfe_neg_tz_edited.pdf";
    document->saveAs(out);
    document.reset();
    context.reset();

    // Fresh, isolated fitz context to read the saved file back.
    std::vector<EditedGlyph> glyphs;
    fz_context* ctx = fz_new_context(nullptr, nullptr, FZ_STORE_DEFAULT);
    fz_register_document_handlers(ctx);
    fz_document* doc = nullptr;
    fz_stext_page* stext = nullptr;
    fz_try(ctx) {
        doc = fz_open_document(ctx, out.string().c_str());
        stext = fz_new_stext_page_from_page_number(ctx, doc, 0, nullptr);
        for (fz_stext_block* b = stext->first_block; b; b = b->next) {
            if (b->type != FZ_STEXT_BLOCK_TEXT) continue;
            for (fz_stext_line* ln = b->u.t.first_line; ln; ln = ln->next) {
                std::u32string lineText;
                std::vector<EditedGlyph> lineGlyphs;
                for (fz_stext_char* ch = ln->first_char; ch; ch = ch->next) {
                    lineText.push_back(static_cast<char32_t>(ch->c));
                    lineGlyphs.push_back({static_cast<char32_t>(ch->c), ch->argb, ch->quad});
                }
                if (lineText.find(U"SHOP") != std::u32string::npos)
                    glyphs = lineGlyphs;
            }
        }
    }
    fz_always(ctx) {
        if (stext) fz_drop_stext_page(ctx, stext);
        if (doc) fz_drop_document(ctx, doc);
    }
    fz_catch(ctx) { /* leave glyphs empty -> assertions fail loudly */ }
    fz_drop_context(ctx);
    return glyphs;
}

} // namespace

// Bug 1: the grey (#dbd0d0) fill must survive the edit -- not fall back to black.
TEST(NegTzGreyTextEdit, PreservesOriginalFillColor) {
    auto glyphs = editAndReadBack();
    ASSERT_FALSE(glyphs.empty()) << "edited 'SHOP TO' line not found after round-trip";

    // The 'O' we introduced (index 1 of "SHOP") must be grey, not black.
    const EditedGlyph& g = glyphs.size() > 1 ? glyphs[1] : glyphs[0];
    int r = (g.argb >> 16) & 0xFF;
    int gg = (g.argb >> 8) & 0xFF;
    int b = g.argb & 0xFF;
    EXPECT_GT(r, 0x60) << "edited glyph is (near) black -- original grey color lost"
                       << " argb=" << std::hex << g.argb;
    // Close to the source grey #dbd0d0 (tolerant of sRGB rounding).
    EXPECT_NEAR(r, 0xDB, 24);
    EXPECT_NEAR(gg, 0xD0, 24);
    EXPECT_NEAR(b, 0xD0, 24);
}

// Bug 2: the edited run must not be horizontally mirrored. Under the ambient
// -100 Tz, an un-neutralized replacement renders each glyph flipped (upper-right
// left of upper-left) and advancing right-to-left.
TEST(NegTzGreyTextEdit, ReplacementNotMirrored) {
    auto glyphs = editAndReadBack();
    ASSERT_GE(glyphs.size(), 2u) << "need >=2 edited glyphs to check direction";

    // Per-glyph: a non-mirrored glyph has upper-right x > upper-left x.
    const fz_quad& q = glyphs.front().quad;
    EXPECT_GT(q.ur.x, q.ul.x)
        << "first edited glyph is horizontally mirrored (quad ur.x <= ul.x)";

    // Run direction: successive glyph origins advance left-to-right.
    EXPECT_GT(glyphs.back().quad.ul.x, glyphs.front().quad.ul.x)
        << "edited run advances right-to-left -- text is mirrored";
}
